using System.Reflection;
using TownOfHost;
using TownOfHost.Modules.MainMenu;
using UnityEngine;
using Obj=UnityEngine.Object;

partial class Program
{
 static (MainMenuManager menu,SeasideMainMenuPatch.HomeView view,FriendsListUI ui,PassiveButton row,Renderer renderer,ControllerUiElementsState home) FriendFixture(bool separateState=true)
 {
  var x=Setup();BindHome(x);
  var ui=new GameObject("NativeFriendsPanel").AddComponent<FriendsListUI>();
  ui.gameObject.OwnScene=new(){handle=99,name="DontDestroyOnLoad",isLoaded=true};
  ui.transform.position=new(3.1f,.2f,-4);FriendsListUI.Instance=ui;
  var row=new GameObject("NativeFriendRow").AddComponent<PassiveButton>();row.transform.SetParent(ui.transform,false);
  row.gameObject.AddComponent<BoxCollider2D>();row.Colliders=row.GetComponentsInChildren<Collider2D>();
  var r=row.gameObject.AddComponent<SpriteRenderer>();r.sortingOrder=2;
  var home=ControllerManager.Instance.CurrentUiState;
  var native=new ControllerUiElementsState();native.SelectableUiElements.Add(row);native.CurrentSelection=row;
  ui.CloseAction=()=>ControllerManager.Instance.CurrentUiState=home;
  var original=Obj.Objects.Single(g=>g.name=="FriendOriginal").GetComponent<PassiveButton>();
  original.OnClick.AddListener(()=>{
   if(!(bool)Call("FriendsOpening"))return;
   ui.Open();if(separateState)ControllerManager.Instance.CurrentUiState=native;
   Call("FriendsOpened",ui);
  });
  return(x.menu,x.view,ui,row,r,home);
 }
 static void OpenFriend((MainMenuManager menu,SeasideMainMenuPatch.HomeView view,FriendsListUI ui,PassiveButton row,Renderer renderer,ControllerUiElementsState home) x)=>Proxy("Friends").OnClick.Invoke();
 static void CloseFriend(FriendsListUI ui,bool argument=false){if((bool)Call("FriendsClosing",ui,argument))ui.Close(argument);}
 static void FriendsPanelTests()
 {
  Test("friends native event opens over seaside instead of hiding background",()=>{var x=FriendFixture();OpenFriend(x);Check(x.view.Visible&&x.ui.IsOpen&&x.view.FriendsBlocking&&!(bool)Call("PopupOpen"));x.view.Dispose();});
  Test("unmanaged friends still uses safe native popup behaviour",()=>{var x=Setup();BindHome(x);var ui=new GameObject("Unmanaged").AddComponent<FriendsListUI>();FriendsListUI.Instance=ui;ui.IsOpen=true;Check((bool)Call("PopupOpen"));Call("Tick",x.menu);Check(!x.view.Visible);x.view.Dispose();});
  foreach(float aspect in new[]{4f/3,16f/9,21f/9,9f/16})
  {
   Test("friends opens right to native position without resizing: "+aspect,()=>{var x=FriendFixture();Camera.main.aspect=aspect;var start=x.ui.transform.position;var scale=x.ui.transform.localScale;var parent=x.ui.transform.parent;OpenFriend(x);Check(x.ui.transform.position.x>start.x+Camera.main.orthographicSize*2*aspect);float last=x.ui.transform.position.x;for(int i=0;i<17;i++){Time.frameCount++;x.view.Tick(true);Check(x.ui.transform.position.x<=last+.0001);last=x.ui.transform.position.x;Near(x.ui.transform.position.y,start.y);Near(x.ui.transform.position.z,start.z);Near(x.ui.transform.localScale.x,scale.x);Near(x.ui.transform.localScale.y,scale.y);Check(x.ui.transform.parent==parent&&x.view.Visible);}Near(last,start.x);x.view.Dispose();});
   Test("friends exits to right and closes native exactly once: "+aspect,()=>{var x=FriendFixture();Camera.main.aspect=aspect;OpenFriend(x);Pump(x.view);CloseFriend(x.ui);float last=x.ui.transform.position.x;for(int i=0;i<15;i++){Time.frameCount++;x.view.Tick(true);Check(x.ui.transform.position.x>=last-.0001&&x.ui.CloseCalls==0);last=x.ui.transform.position.x;}Pump(x.view,3);Check(x.ui.CloseCalls==1&&!x.ui.LastCloseArgument&&!x.view.FriendsBlocking&&x.view.Visible);Near(x.ui.transform.position.x,3.1);x.view.Dispose();});
  }
  Test("friends uses unscaled 0.32 second smoothstep and holds at rest",()=>{var s=new SeasidePanelSlide();Near(s.Offset,1);s.Advance(.08);Near(s.Openness,.25);s.Advance(.08);Near(s.Offset,.5);s.Advance(.08);s.Advance(.08);Near(s.Offset,0);s.Advance(10);Near(s.Offset,0);s.Close();s.Advance(.08);Check(s.Offset>0);});
  foreach(double invalid in new[]{double.NaN,double.PositiveInfinity,double.NegativeInfinity,-1d})Test("invalid panel delta ignored: "+invalid,()=>{var s=new SeasidePanelSlide();s.Advance(.08);var before=s.Offset;s.Advance(invalid);Near(before,s.Offset);});
  Test("zero and stalled frames do not teleport panel or complete a close",()=>{var s=new SeasidePanelSlide();s.Advance(0);Near(s.Offset,1);s.Advance(100);Check(s.Openness>0&&s.Openness<1);s.Close();s.Advance(0);Check(!s.Finished);});
  Test("only one advance per rendered frame",()=>{var x=FriendFixture();OpenFriend(x);Time.frameCount++;x.view.Tick(true);float p=x.ui.transform.position.x;for(int i=0;i<5;i++)x.view.Tick(true);Near(x.ui.transform.position.x,p);x.view.Dispose();});
  Test("native list keeps controller navigation and enabled row hit areas",()=>{var x=FriendFixture();OpenFriend(x);var state=ControllerManager.Instance.CurrentUiState;Pump(x.view);Check(state==ControllerManager.Instance.CurrentUiState&&state.CurrentSelection==x.row&&state.SelectableUiElements.Single()==x.row&&x.row.Colliders[0].enabled);x.row.OnClick.Invoke();Check(x.row.OnClick.Calls==1);x.view.Dispose();});
  Test("background buttons cannot receive click or direct activation under friends",()=>{var x=FriendFixture();OpenFriend(x);foreach(var target in SeasideMenuLayout.Targets){var b=Proxy(target.Id);Check(b.Colliders.All(c=>!c.enabled));Check(!(bool)Call("StartupClick",b));b.OnClick.Invoke();}Check(x.view.Visible&&!x.view.Transitioning&&x.menu.settingsButton.OnClick.Calls==0);Check((bool)Call("StartupClick",x.row));x.view.Dispose();});
  Test("background updater entry cannot run behind friends",()=>{var x=Setup();x.view.Dispose();int calls=0;MainMenuManagerPatch.UpdateButton=new(x.menu.transform,"Updater",new(),Color.white,Color.white,()=>calls++,"",true);var z=new SeasideMainMenuPatch.HomeView(x.menu);BindHome((x.menu,z));var ui=new GameObject("NativeFriends").AddComponent<FriendsListUI>();FriendsListUI.Instance=ui;ui.Open();Call("FriendsOpened",ui);Proxy("Update").OnClick.Invoke();Check(calls==0);z.Dispose();});
  Test("opening friends cancels pending press instead of triggering delayed Play",()=>{var x=FriendFixture();Proxy("Play").OnClick.Invoke();Pump(x.view,3);OpenFriend(x);Pump(x.view,30);Check(!x.view.Transitioning&&x.menu.playButton.OnClick.Calls==0);Neutral("Play");x.view.Dispose();});
  Test("repeated native open reverses current position without repushing navigation",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view,5);CloseFriend(x.ui);Pump(x.view,2);var p=x.ui.transform.position.x;var state=ControllerManager.Instance.CurrentUiState;Check(!(bool)Call("FriendsOpening"));Call("FriendsOpened",x.ui);Near(x.ui.transform.position.x,p);Pump(x.view);Near(x.ui.transform.position.x,3.1);Check(state==ControllerManager.Instance.CurrentUiState&&x.ui.CloseCalls==0);x.view.Dispose();});
  Test("repeated close does not reset exit clock",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view);for(int i=0;i<17;i++){CloseFriend(x.ui);Time.frameCount++;x.view.Tick(true);if(x.ui.CloseCalls>0)break;}Check(x.ui.CloseCalls==1);x.view.Dispose();});
  Test("home navigation restores after native close",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view);CloseFriend(x.ui);Pump(x.view);Check(ControllerManager.Instance.CurrentUiState==x.home&&x.home.SelectableUiElements.Contains(Proxy("Play")));Check(Proxy("Play").Colliders[0].enabled);x.view.Dispose();});
  Test("native same-state navigation is not replaced while list is open",()=>{var x=FriendFixture(false);OpenFriend(x);x.home.SelectableUiElements=new(){x.row};x.home.CurrentSelection=x.row;Pump(x.view);Check(x.home.SelectableUiElements.Single()==x.row);CloseFriend(x.ui);Pump(x.view);Check(x.home.SelectableUiElements.Contains(Proxy("Play")));x.view.Dispose();});
  Test("modal state is not stolen on panel disable",()=>{var x=FriendFixture();OpenFriend(x);var modal=new ControllerUiElementsState();ControllerManager.Instance.CurrentUiState=modal;x.ui.IsOpen=false;Call("FriendsDisabled",x.ui);Check(ControllerManager.Instance.CurrentUiState==modal&&!x.view.FriendsBlocking);x.view.Dispose();});
  Test("panel close preserves independent native row order and restores it",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view);Check(x.renderer.sortingOrder==22);var other=new GameObject("Notification").AddComponent<SpriteRenderer>();other.transform.SetParent(x.ui.transform,false);other.sortingOrder=4;Pump(x.view,1);Check(other.sortingOrder==24);CloseFriend(x.ui);Pump(x.view);Check(x.renderer.sortingOrder==2&&other.sortingOrder==4);x.view.Dispose();});
  Test("native panel descendant renderers and colliders are released from initial home snapshots",()=>{var x=Setup();var ui=new GameObject("NativeFriends").AddComponent<FriendsListUI>();ui.transform.SetParent(x.menu.transform,false);FriendsListUI.Instance=ui;var row=new GameObject("Row").AddComponent<PassiveButton>();row.transform.SetParent(ui.transform,false);var r=row.gameObject.AddComponent<SpriteRenderer>();var c=row.gameObject.AddComponent<BoxCollider2D>();BindHome(x);Check(r.enabled&&c.enabled);ui.Open();Call("FriendsOpened",ui);Pump(x.view);Check(r.enabled&&c.enabled);x.view.Dispose();});
  Test("resize uses new viewport width while preserving native panel dimensions",()=>{var x=FriendFixture();OpenFriend(x);Camera.main.aspect=4f/3;Time.frameCount++;x.view.Tick(true);Check(x.ui.transform.localScale.x==1);Camera.main.aspect=21f/9;Pump(x.view);Near(x.ui.transform.position.x,3.1);Near(x.ui.transform.position.y,.2);x.view.Dispose();});
  Test("native anchoring update during slide becomes the new resting position",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view,3);x.ui.transform.position=new(4,.7f,-4);Pump(x.view);Near(x.ui.transform.position.x,4);Near(x.ui.transform.position.y,.7);CloseFriend(x.ui);Pump(x.view);Near(x.ui.transform.position.x,4);x.view.Dispose();});
  Test("scaled native parent retains parent scale and native local scale",()=>{var x=FriendFixture();var parent=new GameObject("NativeParent");parent.transform.localScale=new(2,2,1);x.ui.transform.SetParent(parent.transform,true);var scale=x.ui.transform.localScale;OpenFriend(x);Pump(x.view);Near(x.ui.transform.position.x,3.1);Near(x.ui.transform.localScale.x,scale.x);Near(parent.transform.localScale.x,2);x.view.Dispose();});
  Test("forty open-close cycles leave no objects or position drift",()=>{var x=FriendFixture();int count=Obj.Objects.Count;for(int i=0;i<40;i++){x.ui.gameObject.SetActive(true);OpenFriend(x);Pump(x.view);CloseFriend(x.ui);Pump(x.view);Near(x.ui.transform.position.x,3.1);Check(!x.view.FriendsBlocking&&x.view.Visible&&Obj.Objects.Count==count);}Check(x.ui.CloseCalls==40);x.view.Dispose();});
  Test("native OnDisable restores panel and input without a duplicate close",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view,4);x.ui.gameObject.SetActive(false);x.ui.IsOpen=false;Call("FriendsDisabled",x.ui);Check(!x.view.FriendsBlocking&&x.ui.CloseCalls==0&&Proxy("Play").Colliders[0].enabled);Near(x.ui.transform.position.x,3.1);x.view.Dispose();});
  Test("native closed state without callback releases adapter",()=>{var x=FriendFixture();OpenFriend(x);x.ui.IsOpen=false;Pump(x.view,1);Check(!x.view.FriendsBlocking);Near(x.ui.transform.position.x,3.1);x.view.Dispose();});
  Test("leaving menu restores native presentation once and removes background",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view,3);Call("LeavingHome");Check(!x.view.Visible&&!x.view.FriendsBlocking&&x.ui.CloseCalls==1);Near(x.ui.transform.position.x,3.1);x.view.Dispose();});
  Test("game scene cannot acquire a friends adapter",()=>{var x=FriendFixture();GameScene();x.ui.Open();Check((bool)Call("FriendsOpening"));Call("FriendsOpened",x.ui);Check(!x.view.FriendsBlocking);x.view.Dispose();});
  Test("scene teardown releases friends without restoring stale game snapshots",()=>{var x=FriendFixture();OpenFriend(x);GameScene();Call("Tick",x.menu);Check(!x.view.Visible&&!x.view.FriendsBlocking&&Home==null&&x.ui.CloseCalls==0);});
  Test("error popup closes panel and preserves native modal accessibility",()=>{var x=FriendFixture();OpenFriend(x);var popup=new GameObject("ImportantError").AddComponent<GenericPopup>();Call("GenericOpening",popup);Call("Tick",x.menu);Check(!x.view.Visible&&!x.view.FriendsBlocking&&(bool)Call("StartupClick",x.row));x.view.Dispose();});
  Test("missing camera restores input and native panel safely",()=>{var x=FriendFixture();OpenFriend(x);Camera.main=null;Pump(x.view,1);Check(!x.view.FriendsBlocking&&!x.view.Visible&&x.ui.CloseCalls==1);x.view.Dispose();});
  Test("missing native instance falls back without disabling all home controls",()=>{var x=Setup();BindHome(x);Proxy("Friends").OnClick.Invoke();Check(!x.view.Visible&&x.menu.playButton.GetComponent<Collider2D>().enabled);x.view.Dispose();});
  Test("dispose mid-slide is idempotent and restores the native original",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view,3);x.view.Dispose();x.view.Dispose();Check(x.ui.CloseCalls==1&&!x.view.FriendsBlocking&&x.renderer.sortingOrder==2);Near(x.ui.transform.position.x,3.1);});
  Test("F8 never alters the friends panel or menu",()=>{var x=FriendFixture();OpenFriend(x);Input.F8=true;Pump(x.view);Check(Input.F8&&x.view.Visible&&x.view.FriendsBlocking);x.view.Dispose();});
  foreach(bool disabled in new[]{false,true})Test("friends slide does not alter wave preference: "+disabled,()=>{var x=FriendFixture();TownOfHost.Main.DisableWaveAnimation.Value=disabled;OpenFriend(x);Pump(x.view);CloseFriend(x.ui);Pump(x.view);Check(TownOfHost.Main.DisableWaveAnimation.Value==disabled&&!x.view.Transitioning);x.view.Dispose();});
  Test("background version and notification count remain live",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view);Check(Text("ShellVersion").text.Contains("TOH-Shell")&&Text("GameVersion").text=="v19.8a (build num: 7492)"&&Text("FriendsLabel").text.Contains("3"));x.view.Dispose();});
  Test("late unsupported friends scene remains native-only",()=>{var x=FriendFixture();x.ui.gameObject.OwnScene=new(){handle=3,isLoaded=true,name="OtherScene"};OpenFriend(x);Check(!x.view.FriendsBlocking&&(bool)Call("PopupOpen"));x.view.Dispose();});
  Test("native force close is immediate and never deferred",()=>{var x=FriendFixture();OpenFriend(x);Pump(x.view,3);CloseFriend(x.ui,true);Check(x.ui.CloseCalls==1&&x.ui.LastCloseArgument&&!x.view.FriendsBlocking);Near(x.ui.transform.position.x,3.1);x.view.Dispose();});
  Test("unexpected friends ancestor cannot move the whole menu",()=>{var x=FriendFixture();x.menu.transform.SetParent(x.ui.transform,true);OpenFriend(x);Check(!x.view.FriendsBlocking);Near(x.ui.transform.position.x,3.1);x.view.Dispose();});
  Test("forced close does not change native game navigation state on scene exit",()=>{var x=FriendFixture();OpenFriend(x);GameScene();var game=new ControllerUiElementsState();ControllerManager.Instance.CurrentUiState=game;Call("Tick",x.menu);Check(ControllerManager.Instance.CurrentUiState==game&&x.ui.CloseCalls==0);});

  Test("native parent movement during opening never accumulates the animated offset",()=>{var x=FriendFixture();var parent=new GameObject("NativeAnchor");x.ui.transform.SetParent(parent.transform,true);OpenFriend(x);Pump(x.view,3);parent.transform.position=new(2,0,0);Pump(x.view);Near(x.ui.transform.position.x,5.1);Near(x.ui.transform.localPosition.x,3.1);CloseFriend(x.ui);Pump(x.view);Near(x.ui.transform.localPosition.x,3.1);x.view.Dispose();});
  Test("native parent rescale retains native size policy and does not drift",()=>{var x=FriendFixture();var parent=new GameObject("NativeAnchor");x.ui.transform.SetParent(parent.transform,true);OpenFriend(x);Pump(x.view,3);parent.transform.localScale=new(1.5f,1.5f,1);Pump(x.view);Near(x.ui.transform.localPosition.x,3.1);Near(x.ui.transform.localScale.x,1);Near(parent.transform.localScale.x,1.5);CloseFriend(x.ui);Pump(x.view);Near(x.ui.transform.localPosition.x,3.1);x.view.Dispose();});
  Test("native mirrored parent still slides out towards screen right",()=>{var x=FriendFixture();var parent=new GameObject("MirroredNativeParent");parent.transform.localScale=new(-1,1,1);x.ui.transform.SetParent(parent.transform,true);OpenFriend(x);Check(x.ui.transform.position.x>3.1);Pump(x.view);Near(x.ui.transform.position.x,3.1);CloseFriend(x.ui);Pump(x.view,4);Check(x.ui.transform.position.x>3.1);Pump(x.view);Near(x.ui.transform.position.x,3.1);x.view.Dispose();});

 }
